from pathlib import Path
import re,json,hashlib,subprocess
W=Path(__file__).resolve().parent;D=W/'sources/review-p134a-p151'
IDS='p134a p134b p135 p136 p137 p138 p139 p140 p141 p142 p143 p144 p145 p145a p146 p147 p148 p149 p150 p151'.split()
def blocks():
 out={}
 for p in (W/'commentary').glob('*.md'):
  a=re.split(r'^=== (\S+)\s*$',p.read_text(),flags=re.M)
  for i in range(1,len(a),2):out[a[i]]=a[i+1].strip()
 return out
assert not (D/'before-commentary.json').exists(), 'Preserved baseline exists; do not replay this one-time edit script'
before=blocks();(D/'before-commentary.json').write_text(json.dumps(before,ensure_ascii=False,indent=2)+'\n')
(D/'baseline-commit.txt').write_text(subprocess.check_output(['git','rev-parse','HEAD'],cwd=W,text=True))
# Preserve the previous bounded report; the orchestrator removed the working copy.
prior=subprocess.check_output(['git','show','HEAD:review-result.json'],cwd=W)
(D/'prior-review-result.json').write_bytes(prior)
replacements={
'p134a':'''§ 134a ordnet den Datenfluss für die landesrechtlich zuständigen Kontrollbehörden, nicht eine allgemeine Datensammlung über regionale Unternehmen. Absatz 1 Satz 1 begrenzt jede Verarbeitung, auch die nicht personenbezogener Daten, auf die Erforderlichkeit für Kontrollen nach § 134 Absatz 1. Satz 2 unterscheidet Betriebe, Erzeuger, die Bundesnetzagentur als Koordinierungsstelle für digitale Dienste und die unionsrechtlichen Kooperationspartner. Beim dritten Weg sind der Bezug zu rechtswidrigen Online-Inhalten und der Vorbehalt des Artikels 84 der Verordnung (EU) 2022/2065 ausdrücklich zu beachten. Daraus folgt keine unbeschränkte Weitergabe sämtlicher Aufsichtsdaten.

Die Übermittlung durch die genannten inländischen Behörden und Stellen ist in Absatz 1 Satz 3 als Pflicht formuliert. Davon unterscheidet Satz 4 die Möglichkeit jeder öffentlichen Stelle, von Amts wegen Hinweise auf geschützte eingetragene Angaben betreffende Verletzungshandlungen samt zugehörigen personenbezogenen Daten zu übermitteln. Ein privater Wettbewerber erhält dadurch keinen behördlichen Aktenzugang. Absatz 2 legt die Löschung drei Jahre nach Ablauf des Erhebungsjahres fest; der Beginn hängt nicht vom späteren Abschluss des Kontrollvorgangs ab.

Absatz 3 trennt drei Empfängerzwecke: Bußgeldverfahren nach § 145 Absätze 2 bis 4, Verletzungsabwehr beziehungsweise Amtshilfe bei den Kooperationspartnern und die Durchsetzung beziehungsweise Überwachung des digitalen Diensterechts durch die Bundesnetzagentur. Die ausdrückliche Erlaubnis der Empfänger zur zweckgebundenen Erhebung und Weiterverarbeitung erfasst Satz 1 Nummern 2 und 3. Die Bußgeldstelle nach Nummer 1 wird in dieser Anschlussregel nicht mitgenannt. Fiktiv erhebt eine Kontrollstelle im Februar 2026 Verkäuferdaten. Für ihre eigene Speicherung endet die gesetzliche Frist mit Ablauf 2029; bei einer Übermittlung sind zusätzlich Empfänger, konkrete Befugnis und Zweck zu dokumentieren. Eine Strafanzeige oder ein fortbestehendes wirtschaftliches Interesse ersetzt keine andere tragfähige Speichergrundlage.''',
'p134b':'''Die Zusammenarbeit nach Absatz 1 ist als behördliche Aufgabe ausgestaltet: Die Kontrollbehörden stellen erforderliche Informationen und Unterlagen bereit, führen geeignete Untersuchungen oder andere angemessene Maßnahmen durch und beteiligen sich an Untersuchungen, die in einem anderen Mitgliedstaat eingeleitet wurden. Gegenstand ist die Unterstützung nach den genau bezeichneten Bestimmungen des Artikels 62 der Verordnung (EU) 2023/2411. Die Norm erklärt eine ausländische Anfrage nicht selbst zu einer unbegrenzten Eingriffsbefugnis; Erforderlichkeit und Angemessenheit müssen für die jeweilige Maßnahme gewahrt bleiben.

Absatz 2 formuliert die Übermittlung personenbezogener Daten als Befugnis. Sie setzt sowohl den Kontrollzweck im Empfängerstaat als auch die Erforderlichkeit im Rahmen der bezeichneten Unterstützung und Kooperation voraus. Zweck und vorgesehener Löschungszeitpunkt sind der ausländischen Behörde mitzuteilen. Diese konkrete Informationspflicht geht über die bloße Benennung des Datenempfängers hinaus. Die in § 134a Absatz 2 geregelte Löschungsfrist der deutschen Kontrollbehörde wird dadurch nicht automatisch zu einer umfassenden Regelung des ausländischen Aktenrechts.

Fiktiv bittet eine französische Kontrollbehörde um Herkunftsnachweise für in Deutschland gefertigte Handwerkswaren. Die deutsche Stelle kann die betreffenden Produktionsunterlagen bereitstellen und eine geeignete Untersuchung durchführen. Bei darin enthaltenen Beschäftigtendaten sind Auswahl, Kontrollbezug, Übermittlungszweck und vorgesehene Löschung gesondert festzuhalten. Eine unselektierte Gesamtpersonalakte lässt sich nicht schon mit der grenzüberschreitenden Lieferkette rechtfertigen. Die Amtshilfe begründet auch keinen privaten Auskunftsanspruch der konkurrierenden Erzeuger; dafür sind die Voraussetzungen des § 135 zu prüfen.''',
'p135':'''Absatz 1 verbindet das unionsrechtlich bestimmte Verbot des Artikels 40 mit nationalen privaten Durchsetzungsinstrumenten. Erforderlich sind eine widerrechtliche Handlung im geschäftlichen Verkehr sowie Wiederholungsgefahr oder eine erstmals drohende Zuwiderhandlung. Verschulden ist für den Unterlassungsanspruch hier nicht genannt. Die vier Berechtigtengruppen sind eigenständig zu prüfen: Bei der Erzeugervereinigung genügt entweder die Eintragung in ihrem Namen oder der Schutz der Angabe innerhalb ihres Tätigkeitsbereichs; beim einzelnen Erzeuger verlangt Nummer 2 das Nutzungsrecht nach Artikel 47. Hinzu kommen die gesetzlich bezeichneten Handwerksorganisationen und Industrie- und Handelskammern. Allgemeine Verbundenheit mit einer Region genügt nicht.

Der Schlussverweis in Absatz 1 ist keine pauschale Übernahme aller Markenansprüche. § 14a Absatz 2 betrifft den Nachweis zum endgültigen Bestimmungsland im dort bezeichneten Zollverfahren. §§ 18 bis 19a und 19c eröffnen entsprechend insbesondere Vernichtung und Rückruf, Herkunfts- und Vertriebswegauskunft, Vorlage und Besichtigung sowie Urteilsbekanntmachung. Die jeweils eigenen Voraussetzungen und Grenzen, etwa Verhältnismäßigkeit und Vertraulichkeit, bleiben bei der entsprechenden Anwendung maßgeblich.

Absatz 2 verweist gesondert auf § 128 Absätze 2 und 3: Ersatz des kausalen Schadens verlangt Vorsatz oder Fahrlässigkeit und steht dem berechtigten Nutzer zu; der Verletzergewinn kann bei der Bemessung berücksichtigt werden. Hinzu kommen die dortigen Folge- und Haftungsregeln einschließlich § 19b, § 14 Absatz 7 und § 19d. Die besondere Geltendmachung in Erzeugernamen darf nur die Vereinigung betreiben, in deren Namen die Angabe eingetragen ist, und nur mit Zustimmung der berechtigten Erzeuger. Ihr größerer Kreis von Unterlassungsbefugnissen bedeutet keinen eigenen Anspruch auf sämtliche Schäden ihrer Mitglieder. Absatz 3 lässt Wettbewerbsansprüche unberührt.

Fiktiv vertreibt ein Händler nicht spezifikationsgemäße Schneidwaren unter einer eingetragenen Angabe. Eine zuständige Kammer kann die Unterlassungsberechtigung aus Absatz 1 ableiten. Für den Produktionsausfall eines einzelnen berechtigten Herstellers sind dagegen Schaden, Verschulden und Anspruchsinhaberschaft festzustellen. Eine nur nach ihrem Tätigkeitsbereich berechtigte Vereinigung erhält nicht allein dadurch die besondere Befugnis des Absatzes 2 Satz 2.''',
'p139':'''Absatz 1 ermächtigt das Bundesministerium der Justiz und für Verbraucherschutz zu ergänzenden Schutzbestimmungen im Einvernehmen mit dem Bundesministerium für Wirtschaft und Energie und mit Zustimmung des Bundesrates. Erfasst sind sowohl Angaben nach der Verordnung (EU) 2023/2411 als auch international geschützte Angaben. Bei unionsrechtlichen Angaben bindet die Ermächtigung die Regelung an Erfordernisse aus dem Unionsrecht; Satz 3 erfasst außerdem ausdrücklich zugelassene ergänzende Vorschriften. Die beispielhafte Liste betrifft Kennzeichnung, Nutzungsberechtigung, Voraussetzungen und Verfahren bei Verbringen, Einfuhr oder Ausfuhr sowie das Kontrollverfahren vor und nach dem Inverkehrbringen. Die Ermächtigung allein begründet noch keine bestimmte zusätzliche Etikettierungspflicht.

Absatz 2 verteilt andere Regelungsaufgaben auf die Landesregierungen. Nummer 1 betrifft die unionsrechtlich begrenzte Einbindung öffentlicher Stellen und sonstiger Interessenträger in Erzeugergemeinschaften. Nummer 2 betrifft die Übertragung von Kontrollaufgaben auf Produktzertifizierungsstellen oder natürliche Personen und deren Zulassung. Durch Rechtsverordnung kann die Ermächtigung ganz oder teilweise an andere Behörden weitergegeben werden. Dem DPMA sind aktuelle Namen und Kontaktdaten sowohl der Kontrollbehörden nach § 134 Absatz 1 als auch der bezeichneten Zertifizierungsstellen und Personen mitzuteilen; diese Meldung ersetzt nicht deren Zulassung.

Fiktiv möchte ein privates Prüfinstitut Kontrollen regionaler Keramik übernehmen. Ein Vertrag mit dem Erzeugerverband belegt weder die öffentlich-rechtliche Aufgabenübertragung noch die erforderliche Zulassung. Beides ist anhand der tatsächlich erlassenen Landesregelung zu prüfen. Ebenso folgt aus einem Verordnungsverstoß nicht automatisch ein Bußgeld: § 145 Absatz 2 Nummer 2 verlangt für die dort bezeichneten Verordnungen einen bestimmten Rückverweis und erfasst nicht unterschiedslos jede Ermächtigungsalternative des § 139.

Praktische Checkliste: Produkt und Schutzsystem bestimmen; Registerstatus und Spezifikationsversion belegen; zuständige Kontrollstelle und wirksame Delegation prüfen; bei Datenweitergabe Erforderlichkeit, Empfängerzweck und Löschung erfassen; für Unterlassung und Schadensersatz die jeweilige Berechtigung gesondert nachweisen; Verordnungsermächtigung und tatsächlich erlassene Pflicht auseinanderhalten.''',
'p143':'''§ 143 sanktioniert bestimmte Marken- und Bezeichnungsverletzungen mit einem selbständigen strafrechtlichen Prüfprogramm. Absatz 1 Nummer 1 betrifft die Identitäts- und Verwechslungsfälle des § 14 Absatz 2 Satz 1 Nummern 1 und 2. Nummer 2 verlangt beim Bekanntheitsschutz zusätzlich die Absicht, Unterscheidungskraft oder Wertschätzung auszunutzen oder zu beeinträchtigen. Nummer 3 erfasst die bezeichneten Vorbereitungshandlungen an Aufmachungen, Verpackungen und Kennzeichnungsmitteln: Die spätere Drittbenutzung müsste untersagt sein; beim Bekanntheitsfall kommt die besondere Ermöglichungsabsicht hinzu. Nummern 4 und 5 übertragen die Unterscheidung auf geschäftliche Bezeichnungen, wiederum mit besonderer Absicht bei der bekannten Bezeichnung. Nicht jede zivilrechtliche Verbotsalternative ist damit ohne weitere Prüfung zugleich strafbewehrt.

Der Grundstrafrahmen beträgt bis zu drei Jahre Freiheitsstrafe oder Geldstrafe. Nach § 15 StGB ist Vorsatz erforderlich; eine bloß fahrlässige Verletzung, die zivilrechtlich Schadensersatz auslösen kann, reicht nicht. Gewerbsmäßiges Handeln oder die in Absatz 2 näher beschriebene Bandenmitgliedschaft führen zum Strafrahmen von drei Monaten bis zu fünf Jahren. Schon das Handeln im geschäftlichen Verkehr aus Absatz 1 belegt noch nicht diese Qualifikation. Absatz 3 erklärt den Versuch für strafbar. Der Strafantrag mit Ausnahme des besonderen öffentlichen Verfolgungsinteresses nach Absatz 4 betrifft die Fälle des Absatzes 1, nicht unterschiedslos jede qualifizierte Tat.

Absatz 5 ermöglicht die Einziehung tatbezogener Gegenstände und verweist auf § 74a StGB. Werden Vernichtungsansprüche nach § 18 im bezeichneten strafprozessualen Entschädigungsverfahren zuerkannt, tritt die dort geregelte Abgrenzung zur Einziehung ein; es handelt sich nicht um eine automatische kumulative Doppelanordnung. Absatz 6 setzt für die öffentliche Bekanntmachung eine Verurteilung, den Antrag des Verletzten und dessen dargelegtes berechtigtes Interesse voraus; die Art ist im Urteil festzulegen. Absätze 1a und 7 bleiben als weggefallene Positionen sichtbar.

Fiktiv lässt ein Händler wissentlich fremde Markenetiketten für eine gefälschte Warenserie herstellen. Vor einer Einordnung nach Nummer 3 sind der konkrete Herstellungsschritt, die untersagte Drittbenutzung und bei einer bekannten Marke die besondere Absicht festzustellen. Vertriebsunterlagen können zugleich für Vorsatz und Qualifikation wichtig sein, ersetzen aber nicht deren getrennte Feststellung.''',
'p144':'''Absatz 1 enthält einen eigenen Straftatbestand für Unionsmarken und benennt ausdrücklich die Fassung der Verordnung (EU) 2017/1001 vom 11. April 2024. Nummer 1 setzt Zeichen- und Waren- beziehungsweise Dienstleistungsidentität voraus. Nummer 2 betrifft Verwechslungsgefahr aufgrund der jeweiligen Identität oder Ähnlichkeit, einschließlich der bezeichneten gedanklichen Verbindung. Nummer 3 ist besonders eng formuliert: Sie nennt unähnliche Waren oder Dienstleistungen, die Bekanntheit in der Gemeinschaft und die Absicht unlauterer Ausnutzung oder Beeinträchtigung ohne rechtfertigenden Grund. Der strafrechtliche Wortlaut darf nicht durch eine weiter gefasste zivilrechtliche Beschreibung des Bekanntheitsschutzes ersetzt werden. Verbot, fehlende Zustimmung, geschäftlicher Verkehr und Vorsatz sind eigenständig zu prüfen; die Eintragung allein belegt noch keine Straftat des Verkäufers.

Absatz 2 übernimmt aus § 143 Absätze 2 bis 6 die Qualifikation, Versuchsstrafbarkeit, Antragsregel, Einziehung und Bekanntmachung. Der Grundstrafrahmen steht dagegen bereits in Absatz 1: bis zu drei Jahre oder Geldstrafe. Für die qualifizierten Fälle gilt der strengere Rahmen der Verweisungsnorm. Nicht übernommen werden die weggefallenen Absätze 1a und 7. Zivilrechtliches Unionsmarkengericht und nationales Strafgericht erfüllen unterschiedliche Aufgaben.

Zur historischen Vorgängernorm hat der BGH, Beschluss vom 21. April 2021, 3 StR 225/20, Rn. 7–11, entschieden, dass die Ersetzung der in Bezug genommenen Gemeinschaftsmarkenverordnung in der dortigen Identitätskonstellation keine Strafbarkeitslücke schuf. Maßgeblich war der im nationalen Tatbestand selbst vollständig beschriebene Handlungsinhalt. Rn. 12–13 betreffen die täterschaftliche Einfuhr ohne eigenhändigen Grenztransport bei entsprechendem Tatbeitrag. Der damalige § 143a ist seit der Neunummerierung von 2026 § 144; der Beschluss erklärt weder jede spätere Verweisungsänderung noch sämtliche Varianten für unproblematisch. Siehe [Fallkarte](cases/bgh-gemeinschaftsmarke-strafbarkeit.md).

Fiktiv bestellt ein Händler wissentlich identisch gekennzeichnete, nicht autorisierte Taschen beim ausländischen Hersteller und organisiert die Lieferung an sein Lager. Dass ein Spediteur die Grenze passiert, schließt eine eigene strafbare Benutzung nicht schon aus. Erforderlich bleiben die Feststellungen zum Einfuhrvorgang, Tatbeitrag und Wissen; bei älteren Taten ist die Tatzeitfassung gesondert zu bestimmen.''',
'p145':'''Die sechs Absätze bündeln unterschiedliche Ordnungswidrigkeiten mit verschiedenen subjektiven Anforderungen und Höchstbeträgen. Absatz 1 Nummer 1 betrifft die öffentlichen Zeichen des § 6a, Nummern 2 bis 4 die Herkunftstäuschung, territoriale Qualitätsanforderungen und den Ruf- beziehungsweise Unterscheidungskraftschutz des § 127 samt genau bezeichneten Erweiterungen. Nummer 4 verlangt die besondere Zielrichtung der Ausnutzung oder Beeinträchtigung. Mangels ausdrücklicher Fahrlässigkeitsanordnung in den Absätzen 1 und 3 gilt dort die Vorsatzregel des § 10 OWiG; die in anderen Absätzen angeordnete Fahrlässigkeit darf nicht auf diese Gruppen übertragen werden.

Absatz 2 erfasst ausdrücklich Vorsatz und Fahrlässigkeit. Nummer 1 nennt bestimmte Behinderungen der Kontrolle nach § 134 Absätze 4 und 5, insbesondere Zutritt, Darlegung der Erzeugnisse, Proben, Unterlagen und Auskünfte. Die Liste ist anhand der konkret vorgeworfenen Handlung zu prüfen; sie sanktioniert nicht pauschal jede Unregelmäßigkeit bei einer Kontrolle. Das Auskunftsverweigerungsrecht aus § 134 Absatz 6 bleibt zu berücksichtigen. Nummer 2 verlangt bei den dort genau bezeichneten Verordnungs- und Anordnungsverstößen zusätzlich, dass die Rechtsverordnung für einen bestimmten Tatbestand auf die Bußgeldnorm verweist. Eine Ermächtigung zum Verordnungserlass genügt dafür nicht.

Absatz 3 benennt für handwerkliche und industrielle geografische Angaben bestimmte Handlungen nach Artikel 40 Absatz 1 Buchstaben a bis c einschließlich der Verweise auf Absätze 3 und 4, jeweils unter der festen Fassungsangabe vom 18. Oktober 2023. Damit wird nicht jede irgendwie denkbare Verletzung der gesamten Verordnung zum Bußgeldtatbestand. Absatz 4 bedroht dagegen ausdrücklich auch die fahrlässige fehlende oder verspätete Eigenerklärung mit Geldbuße. Welche Erklärung wann einzureichen ist, muss aus der dort verwiesenen Unionsbestimmung hervorgehen.

Nach Absatz 5 beträgt der Höchstbetrag 50.000 Euro für Absatz 1 Nummern 2 bis 4 und Absatz 3, 10.000 Euro für Absätze 2 und 4 sowie 5.000 Euro für Absatz 1 Nummer 1. Das ist keine automatische Bußgeldhöhe. Absatz 6 weist nur die letztgenannte Fallgruppe ausdrücklich dem Bundesamt für Justiz zu. Fiktiv legt ein Betriebsleiter fahrlässig angeforderte Kontrollunterlagen zu spät vor. Für Absatz 2 sind ein gedecktes Verlangen und die konkrete Pflichtverletzung festzustellen; daraus folgt weder die Vorsätzlichkeit einer zugleich beanstandeten Herkunftsverwendung noch der für diese andere Fallgruppe geltende höhere Rahmen. Bei Altverstößen ist ergänzend die Sonderregel des § 160 Absatz 1 zu beachten.'''
}
# Preserve substantial existing prose and make targeted corrections in the remaining blocks.
replacements['p137']=before['p137'].replace('§§ 134 bis 136 sowie § 139 gelten entsprechend.','§§ 134 bis 136 sowie § 139 gelten entsprechend; dies umfasst innerhalb der Paragraphenspanne auch die Daten- und Amtshilferegeln der §§ 134a und 134b.')
replacements['p141']=before['p141'].replace('Die Vorschrift verhindert, dass ein auf Wettbewerbsrecht gestützter Anspruch mit Bezug zu den hier geregelten Kennzeichenverhältnissen ausschließlich im dort bezeichneten Wettbewerbsgerichtsstand verfolgt werden muss.','Die Vorschrift löst Ansprüche aus den hier geregelten Kennzeichenverhältnissen, die auf Wettbewerbsrecht gestützt werden, von der Bindung an den in § 14 UWG bezeichneten Gerichtsstand. Der amtlich geprüfte § 14 UWG enthält selbst mehrere örtliche Anknüpfungen und Begrenzungen; § 141 ist deshalb nicht als bloße Erweiterung eines einzigen ausschließlichen Ortsgerichtsstands zu beschreiben.')
replacements['p142']=before['p142'].replace('Absatz 2 passt eigene Anwaltsgebühren und den Umfang einer gegnerischen Kostenerstattung an, wahrt aber bei Kostenlast des Gegners die bezeichnete Abrechnungsmöglichkeit des eigenen Anwalts nach dessen maßgeblichem Wert.','Absatz 2 Satz 1 begrenzt die Gebühren des eigenen Rechtsanwalts auf den Teilwert. Bei eigener Kostenlast oder Kostenübernahme erstattet die begünstigte Partei auch die gegnerisch entrichteten Gerichtsgebühren und Anwaltsgebühren nur nach diesem Teilwert. Trägt dagegen der Gegner die außergerichtlichen Kosten, kann der eigene Rechtsanwalt seine Gebühren von ihm nach dem für den Gegner geltenden Wert beitreiben. Die Zahlungsrichtungen sind damit verschieden; die persönliche Begünstigung gewährt dem Gegner nicht automatisch denselben niedrigeren Wert.')
replacements['p146']=before['p146'].replace('Im EU- und EWR-Verkehr setzt sie tatsächlich stattfindende Zollkontrollen voraus.','Der nationale Tatbestand nennt Einfuhr und Ausfuhr, anders als § 151 nicht zusätzlich die Durchfuhr. Im EU- und EWR-Verkehr setzt er tatsächlich stattfindende Zollkontrollen voraus.')
replacements['p147']=before['p147'].replace('Fehlt sie, ist nach Absatz 4 grundsätzlich nach zwei Wochen ab Mitteilung an den Antragsteller aufzuheben; ein belegter, noch nicht beschiedener gerichtlicher Antrag erlaubt höchstens zwei weitere Wochen.','Liegen die Fälle des Absatzes 3 nicht vor, ist nach Absatz 4 nach zwei Wochen ab Zustellung der Widerspruchsmitteilung an den Antragsteller aufzuheben. Weist dieser nach, dass er die gerichtliche Entscheidung beantragt hat, sie ihm aber noch nicht zugegangen ist, wird die Beschlagnahme höchstens zwei weitere Wochen aufrechterhalten. Die Entscheidung muss also nicht zwingend noch unerlassen sein; auch ihr ausstehender Zugang wird erfasst. Diese zweite Frist hat einen anderen Zustellungsbezug als die Widerspruchsfrist des Absatzes 1.')
assert len(replacements)==12 and set(replacements)<=set(IDS)
for p in (W/'commentary').glob('*.md'):
 s=p.read_text()
 for ident,body in replacements.items():
  pat=r'(?m)(^=== '+re.escape(ident)+r'\s*\n).*?(?=^=== |\Z)'
  s=re.sub(pat,lambda m:m[1]+'\n'+body.strip()+'\n\n',s,flags=re.S)
 if s!=p.read_text():p.write_text(s)
after=blocks();assert all(before[i]==after[i] for i in before if i not in IDS)
assert sum(before[i]!=after[i] for i in IDS)==12
print('12 corrected blocks; 8 assigned retained; 171 unassigned blocks unchanged')
